-- StockAssistant: datos SIMULADOS de Ventas y Marketing exportados de 5174.
-- PostgreSQL 15+. Carga de demostracion, NO migracion del esquema.
-- Fuente: ventas_sandbox_5174(1).sql; SHA256: 6cb107ba63ce0621a71ddc49e3dca373080cc773f752c5746a098b442ef4b3d4
-- Conserva cantidades y fechas originales (historico hasta octubre de 2026).
-- Corrige unicamente el texto mal codificado: auriculares inalambricos (con tilde).
--
-- Contenido: 7 productos, 2 almacenes, 7 configuraciones, 7 saldos y
-- 816 movimientos (7 entradas y 809 despachos), saldo 500 por producto.
-- Reutiliza unidades por codigo; crea solo las que falten.
-- Resuelve nuevos identificadores; no copia IDs ni reinicia secuencias.
-- Resuelve EUR por iso_code; usa el usuario de actualizacion por defecto
-- definido en products, en lugar de copiar el usuario local 1.
-- Si algun codigo de producto/almacen u operation_key del lote existe,
-- ABORTA toda la carga: no sobrescribe ni completa lotes parcialmente cargados.
-- No modifica registros existentes; NO deshabilita restricciones ni triggers.
-- Una transaccion; un error impide confirmar los registros del lote.
-- Las secuencias pueden avanzar aunque se revierta (comportamiento PostgreSQL).
--
-- Requisitos: esquema unificado actual (public.products tabla), tablas de
-- inventario y moneda EUR instaladas; defaults/secuencias operativos.
-- Ejecutar con un rol autorizado para INSERT, SELECT, tablas temporales,
-- secuencias y bloqueos de estas tablas, en la BD de demostracion acordada.
-- Coordinar las automatizaciones: estos registros cuentan en los analisis.
-- NO contiene pedidos, clientes, facturas ni devoluciones; no alimenta todos
-- los modulos ni demuestra precision comercial o entrenamiento de IA.
-- Las fechas son fijas: no garantiza candidatos de Marketing en cualquier fecha.
-- No despliega codigo ni configura claves de SerpAPI/OpenAI.
--
-- Ejecucion por el equipo (conexion/credenciales gestionadas por ellos):
-- psql <opciones-de-conexion> -X -v ON_ERROR_STOP=1 -f ventas_demo_portable.sql
-- Para una prueba reversible de registros, cambiar SOLO el COMMIT final
-- por ROLLBACK (las secuencias pueden avanzar igualmente).
-- Validado en PostgreSQL embebido con esquema representativo; no ejecutado
-- ni validado contra la instancia AWS real.

BEGIN;
SET LOCAL TIME ZONE 'UTC';
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE TEMP TABLE demo_src_inventory_units (LIKE public.inventory_units) ON COMMIT DROP;
CREATE TEMP TABLE demo_src_inventory_warehouses (LIKE public.inventory_warehouses) ON COMMIT DROP;
CREATE TEMP TABLE demo_src_products (LIKE public.products) ON COMMIT DROP;
CREATE TEMP TABLE demo_src_product_inventory_config (LIKE public.product_inventory_config) ON COMMIT DROP;
CREATE TEMP TABLE demo_src_inventory_movements (LIKE public.inventory_movements) ON COMMIT DROP;
CREATE TEMP TABLE demo_src_inventory_stock_levels (LIKE public.inventory_stock_levels) ON COMMIT DROP;

CREATE TEMP TABLE demo_map_units(old_id bigint PRIMARY KEY,new_id bigint UNIQUE NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE demo_map_warehouses(old_id bigint PRIMARY KEY,new_id bigint UNIQUE NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE demo_map_products(old_id bigint PRIMARY KEY,new_id bigint UNIQUE NOT NULL) ON COMMIT DROP;

DO $demo$
DECLARE
    r record;
    v_demo_id bigint;
    eur_id bigint;
BEGIN
    -- Serializa cambios concurrentes durante comprobacion e insercion.
    LOCK TABLE public.inventory_units, public.inventory_warehouses,
        public.products, public.product_inventory_config,
        public.inventory_movements, public.inventory_stock_levels
        IN SHARE ROW EXCLUSIVE MODE;

    IF (SELECT relkind FROM pg_class WHERE oid='public.products'::regclass) NOT IN ('r','p') THEN
        RAISE EXCEPTION 'Se requiere public.products como tabla del catalogo unificado';
    END IF;
    IF EXISTS(SELECT 1 FROM public.products p JOIN demo_src_products s ON p.product_id=s.product_id)
       OR EXISTS(SELECT 1 FROM public.inventory_warehouses w JOIN demo_src_inventory_warehouses s ON w.code=s.code)
       OR EXISTS(SELECT 1 FROM public.inventory_movements m JOIN demo_src_inventory_movements s ON m.operation_key=s.operation_key) THEN
        RAISE EXCEPTION 'Ya existe algun identificador del lote SIMULADO. No se escribe ni duplica. Revisar la carga anterior.';
    END IF;
    SELECT id INTO STRICT eur_id FROM public.inventory_currencies WHERE iso_code='EUR';
    IF EXISTS(SELECT 1 FROM demo_src_products WHERE currency IS DISTINCT FROM 'EUR') THEN
        RAISE EXCEPTION 'El lote debe usar exclusivamente EUR';
    END IF;
    IF EXISTS(SELECT 1 FROM demo_src_inventory_movements WHERE document_id IS NOT NULL OR document_line_id IS NOT NULL OR warehouse_destination_id IS NOT NULL) THEN
        RAISE EXCEPTION 'El lote contiene relaciones externas no soportadas';
    END IF;
    IF EXISTS(SELECT 1 FROM demo_src_inventory_movements
        WHERE quantity<=0 OR quantity IS DISTINCT FROM abs(quantity_signed)
        OR movement_type NOT IN ('receipt','dispatch')
        OR (movement_type='receipt' AND quantity_signed<=0)
        OR (movement_type='dispatch' AND quantity_signed>=0)) THEN
        RAISE EXCEPTION 'Signo o tipo de movimientos incorrecto';
    END IF;

    FOR r IN SELECT * FROM demo_src_inventory_units ORDER BY id LOOP
        v_demo_id := NULL;
        SELECT id INTO v_demo_id FROM public.inventory_units WHERE code=r.code;
        IF v_demo_id IS NULL THEN
            VALUES(r.code,r.name,r.description,r.created_at,r.updated_at) RETURNING id INTO v_demo_id;
        END IF;
    END LOOP;

    FOR r IN SELECT * FROM demo_src_inventory_warehouses ORDER BY id LOOP
        VALUES(r.code,r.name,r.description,r.is_active,r.created_at,r.updated_at) RETURNING id INTO v_demo_id;
    END LOOP;
    FOR r IN SELECT * FROM demo_src_products ORDER BY id LOOP
        VALUES(r.product_id,r.product_name,r.description,r.product_category,r.brand,r.sku,r.product_cost_usd,r.selling_price_usd,r.disabled,r.price,(SELECT new_id FROM demo_map_units WHERE old_id=r.unit),r.final_price,r.discount,r.discount_end_date,eur_id,r.currency,r.user_rating,r.link,r.supplier,r.created_at,r.updated_at) RETURNING id INTO v_demo_id;
    END LOOP;
        SELECT (SELECT new_id FROM demo_map_products WHERE old_id=s.product_id),(SELECT new_id FROM demo_map_units WHERE old_id=s.base_unit_id),s.reorder_point,s.reorder_quantity,s.allow_negative_stock,s.created_at,s.updated_at FROM demo_src_product_inventory_config s;
        SELECT s.movement_type,(SELECT new_id FROM demo_map_products WHERE old_id=s.product_id),(SELECT new_id FROM demo_map_warehouses WHERE old_id=s.warehouse_id),(SELECT new_id FROM demo_map_warehouses WHERE old_id=s.warehouse_destination_id),s.quantity,s.quantity_signed,(SELECT new_id FROM demo_map_units WHERE old_id=s.base_unit_id),s.document_type,s.document_id,s.document_line_id,s.operation_key,s.reason,s.user_name,s.created_at FROM demo_src_inventory_movements s;
        SELECT (SELECT new_id FROM demo_map_products WHERE old_id=s.product_id),(SELECT new_id FROM demo_map_warehouses WHERE old_id=s.warehouse_id),s.physical_qty,s.reserved_qty,s.created_at,s.updated_at FROM demo_src_inventory_stock_levels s;

    IF (SELECT count(*) FROM public.inventory_movements m JOIN demo_map_products p ON p.new_id=m.product_id) <> 816
        OR (SELECT count(*) FROM public.inventory_stock_levels s JOIN demo_map_products p ON p.new_id=s.product_id) <> 7
        OR (SELECT count(*) FROM public.product_inventory_config c JOIN demo_map_products p ON p.new_id=c.product_id) <> 7 THEN
        RAISE EXCEPTION 'No coinciden los recuentos finales. Se revierte la carga';
    END IF;
    IF EXISTS(SELECT 1 FROM demo_map_products p
        WHERE (SELECT sum(m.quantity_signed) FROM public.inventory_movements m WHERE m.product_id=p.new_id) IS DISTINCT FROM 500::numeric
           OR (SELECT sum(s.physical_qty) FROM public.inventory_stock_levels s WHERE s.product_id=p.new_id) IS DISTINCT FROM 500::numeric
           OR (SELECT sum(s.reserved_qty) FROM public.inventory_stock_levels s WHERE s.product_id=p.new_id) IS DISTINCT FROM 0::numeric) THEN
        RAISE EXCEPTION 'Los saldos no coinciden con 500 unidades y cero reservas. Se revierte la carga';
    END IF;
    RAISE NOTICE 'Lote SIMULADO cargado: 7 productos, 816 movimientos. Pendiente COMMIT final.';
END;
$demo$;

-- Informe de correspondencias y cantidades; IDs del DESTINO, no del sandbox.
SELECT p.product_id AS codigo, p.product_name AS producto, p.id AS id_destino,
       count(m.id) FILTER (WHERE m.movement_type='dispatch') AS numero_despachos,
       coalesce(sum(-m.quantity_signed) FILTER (WHERE m.movement_type='dispatch'),0) AS unidades_despachadas,
       sum(m.quantity_signed) AS saldo_movimientos
FROM public.products p JOIN demo_map_products k ON k.new_id=p.id
JOIN public.inventory_movements m ON m.product_id=p.id
GROUP BY p.product_id,p.product_name,p.id ORDER BY p.product_id;

COMMIT;
